    [Fact]public async Task Agent_Executes_Tool_And_Feeds_Result_Back_To_Model()
    {
        var provider=new TwoTurnProvider();var conversations=new InMemoryConversationRepository();var memory=new InMemoryMemoryStore();var settings=new InMemorySettingsRepository(new AppSettings{LongTermMemoryEnabled=false});var registry=new ToolRegistry([new EchoTool()]);var executor=new ToolExecutor(registry,new FixedPermissionService(PermissionDecision.AllowOnce),NullLogger<ToolExecutor>.Instance);var runtime=new AgentRuntime(new FixedProviderFactory(provider),registry,executor,conversations,memory,settings,NullLogger<AgentRuntime>.Instance);var conversation=new Conversation();await conversations.SaveAsync(conversation);var user=new ChatMessage{ConversationId=conversation.Id,Role=MessageRole.User,Content="echo x"};await conversations.SaveMessageAsync(user);var events=new List<ModelEvent>();await foreach(var item in runtime.RunAsync(new(conversation,[user],new ConnectionProfile{Name="x",BaseUrl="https://example.test/v1",Model="m"},new AgentRunOptions())))events.Add(item);provider.Calls.Should().Be(2);provider.SecondRequest!.Messages.Should().Contain(x=>x.Role==MessageRole.Tool&&x.Content=="x");events.OfType<ToolExecutionCompletedEvent>().Should().ContainSingle(x=>x.Succeeded);conversations.Messages.Should().Contain(x=>x.Role==MessageRole.Assistant&&x.Content=="final");
    }
    [Fact]public async Task Regenerated_Response_Target_Remains_The_Parent_When_Tools_Are_Used()
    {
        var provider=new TwoTurnProvider();var conversations=new InMemoryConversationRepository();var registry=new ToolRegistry([new EchoTool()]);var runtime=new AgentRuntime(new FixedProviderFactory(provider),registry,new ToolExecutor(registry,new FixedPermissionService(PermissionDecision.AllowOnce),NullLogger<ToolExecutor>.Instance),conversations,new InMemoryMemoryStore(),new InMemorySettingsRepository(new AppSettings{LongTermMemoryEnabled=false}),NullLogger<AgentRuntime>.Instance);var conversation=new Conversation();await conversations.SaveAsync(conversation);var user=new ChatMessage{ConversationId=conversation.Id,Role=MessageRole.User,Content="echo x"};await conversations.SaveMessageAsync(user);var old=new ChatMessage{ConversationId=conversation.Id,Role=MessageRole.Assistant,Content="old",ParentMessageId=user.Id};await conversations.SaveMessageAsync(old);var target=await conversations.CreateMessageVersionAsync(old.Id,string.Empty);await foreach(var _ in runtime.RunAsync(new(conversation,[user],new ConnectionProfile{Name="x",BaseUrl="https://example.test/v1",Model="m"},new AgentRunOptions(),target.Id))){}var updated=conversations.Messages.Single(x=>x.Id==target.Id);updated.ToolCalls.Should().ContainSingle();var final=conversations.Messages.Single(x=>x.Content=="final");final.ParentMessageId.Should().Be(target.Id);
    }
