    [Fact]public async Task Third_Identical_Tool_Call_Is_Blocked_And_A_Loop_Forces_Synthesis()
    {
        var provider=new IdenticalToolUntilDisabledProvider();var conversations=new InMemoryConversationRepository();var registry=new ToolRegistry([new EchoTool()]);var runtime=new AgentRuntime(new FixedProviderFactory(provider),registry,new ToolExecutor(registry,new FixedPermissionService(PermissionDecision.AllowOnce),NullLogger<ToolExecutor>.Instance),conversations,new InMemoryMemoryStore(),new InMemorySettingsRepository(new AppSettings{LongTermMemoryEnabled=false}),NullLogger<AgentRuntime>.Instance);var conversation=new Conversation();var user=new ChatMessage{ConversationId=conversation.Id,Role=MessageRole.User,Content="loop"};var events=new List<ModelEvent>();await foreach(var item in runtime.RunAsync(new(conversation,[user],new ConnectionProfile{Name="x",BaseUrl="https://example.test/v1",Model="m"},new AgentRunOptions(12,HardMaximumIterations:64))))events.Add(item);provider.Calls.Should().Be(5);events.OfType<ToolExecutionCompletedEvent>().Should().HaveCount(4);events.OfType<ToolExecutionCompletedEvent>().Count(item=>!item.Succeeded&&item.Error!.Contains("loop",StringComparison.OrdinalIgnoreCase)).Should().Be(2);events.OfType<TextDeltaEvent>().Should().ContainSingle(x=>x.Delta=="forced final");
