    [Fact]public async Task Model_Can_Request_Budget_From_A_Concrete_Work_Plan()
    {
        var provider=new PlannedBudgetProvider();var conversations=new InMemoryConversationRepository();var registry=new ToolRegistry([new EchoTool()]);var runtime=new AgentRuntime(new FixedProviderFactory(provider),registry,new ToolExecutor(registry,new FixedPermissionService(PermissionDecision.AllowOnce),NullLogger<ToolExecutor>.Instance),conversations,new InMemoryMemoryStore(),new InMemorySettingsRepository(new AppSettings{LongTermMemoryEnabled=false}),NullLogger<AgentRuntime>.Instance);var conversation=new Conversation();var user=new ChatMessage{ConversationId=conversation.Id,Role=MessageRole.User,Content="plan research"};var events=new List<ModelEvent>();await foreach(var item in runtime.RunAsync(new(conversation,[user],new ConnectionProfile{Name="x",BaseUrl="https://example.test/v1",Model="m"},new AgentRunOptions(2,HardMaximumIterations:8))))events.Add(item);provider.Calls.Should().Be(7);provider.FirstRequest!.Tools.Should().Contain(tool=>tool.Name=="request_work_budget");var budget=events.OfType<ToolExecutionCompletedEvent>().Single(item=>item.Name=="request_work_budget");budget.Succeeded.Should().BeTrue();budget.Output.Should().Contain("\"approvedBudget\":7");var progress=events.OfType<AgentProgressEvent>().Last();progress.IsCompleted.Should().BeTrue();progress.RequestedActionCount.Should().Be(4);progress.RequestedActionCounts.Should().Contain("echo",4);progress.PlannedActions.Should().ContainSingle(action=>action.Tool=="echo"&&action.EstimatedToolCalls==4);var final=conversations.Messages.Single(message=>message.Content=="planned final");final.Metadata[AgentRunMessageMetadata.RequestedActionCount].Should().Be("4");final.Metadata.Should().ContainKey(AgentRunMessageMetadata.DurationMilliseconds);events.OfType<TextDeltaEvent>().Should().ContainSingle(x=>x.Delta=="planned final");
    }
    [Fact]public async Task Second_Python_Memory_Failure_Disables_Python_And_Forces_Final_Synthesis()
    {
