    [Fact]public async Task Full_Tool_Output_Is_Persisted_While_Model_Context_Is_Clipped()
    {
        var provider=new CaptureSecondRequestProvider();var conversations=new InMemoryConversationRepository();var registry=new ToolRegistry([new LargePythonOutputTool()]);var runtime=new AgentRuntime(new FixedProviderFactory(provider),registry,new ToolExecutor(registry,new FixedPermissionService(PermissionDecision.AllowOnce),NullLogger<ToolExecutor>.Instance),conversations,new InMemoryMemoryStore(),new InMemorySettingsRepository(new AppSettings{LongTermMemoryEnabled=false}),NullLogger<AgentRuntime>.Instance);var conversation=new Conversation();var user=new ChatMessage{ConversationId=conversation.Id,Role=MessageRole.User,Content="run"};var events=new List<ModelEvent>();await foreach(var item in runtime.RunAsync(new(conversation,[user],new ConnectionProfile{Name="x",BaseUrl="https://example.test/v1",Model="m"},new AgentRunOptions())))events.Add(item);var completed=events.OfType<ToolExecutionCompletedEvent>().Single();completed.Output.Length.Should().BeGreaterThan(30_000);var modelToolMessage=provider.SecondRequest!.Messages.Single(message=>message.Role==MessageRole.Tool);modelToolMessage.Content.Length.Should().BeLessThan(16_000);modelToolMessage.Content.Should().Contain("truncated only in model context");conversations.Messages.SelectMany(message=>message.ToolCalls).Single().Execution!.Output.Should().Be(completed.Output);
