    [Fact]public async Task Auto_Reasoning_Uses_Model_Classifier_And_Maps_Ultra_To_XHigh()
    {
        var provider=new AutoReasoningProvider();var conversations=new InMemoryConversationRepository();var registry=new ToolRegistry([]);var runtime=new AgentRuntime(new FixedProviderFactory(provider),registry,new ToolExecutor(registry,new FixedPermissionService(PermissionDecision.AllowOnce),NullLogger<ToolExecutor>.Instance),conversations,new InMemoryMemoryStore(),new InMemorySettingsRepository(new AppSettings{LongTermMemoryEnabled=false,ReasoningPreference=ReasoningPreference.Auto}),NullLogger<AgentRuntime>.Instance);var conversation=new Conversation();var user=new ChatMessage{ConversationId=conversation.Id,Role=MessageRole.User,Content="perform a difficult multi-stage investigation"};await foreach(var _ in runtime.RunAsync(new(conversation,[user],new ConnectionProfile{Name="x",BaseUrl="https://example.test/v1",Model="m"},new AgentRunOptions(Reasoning:ReasoningPreference.Auto)))){}provider.ClassifierRequest.Should().NotBeNull();provider.ClassifierRequest!.ReasoningEffort.Should().Be(ReasoningEffort.Low);provider.StreamRequest.Should().NotBeNull();provider.StreamRequest!.ReasoningEffort.Should().Be(ReasoningEffort.XHigh);conversations.Messages.Single(message=>message.Content=="done").Metadata[AgentRunMessageMetadata.ReasoningEffort].Should().Be("XHigh");
    }
    [Fact]public async Task Eta_Deadline_Does_Not_Restart_After_Every_Planned_Action()
    {
        var provider=new PlannedBudgetProvider();var conversations=new InMemoryConversationRepository();var registry=new ToolRegistry([new EchoTool()]);var runtime=new AgentRuntime(new FixedProviderFactory(provider),registry,new ToolExecutor(registry,new FixedPermissionService(PermissionDecision.AllowOnce),NullLogger<ToolExecutor>.Instance),conversations,new InMemoryMemoryStore(),new InMemorySettingsRepository(new AppSettings{LongTermMemoryEnabled=false}),NullLogger<AgentRuntime>.Instance);var conversation=new Conversation();var user=new ChatMessage{ConversationId=conversation.Id,Role=MessageRole.User,Content="plan research"};var events=new List<ModelEvent>();await foreach(var item in runtime.RunAsync(new(conversation,[user],new ConnectionProfile{Name="x",BaseUrl="https://example.test/v1",Model="m"},new AgentRunOptions(2,HardMaximumIterations:8,Reasoning:ReasoningPreference.High))))events.Add(item);var deadlines=events.OfType<AgentProgressEvent>().Where(progress=>!progress.IsCompleted&&progress.PlannedActions.Count>0&&progress.EstimatedCompletionAt is not null).Select(progress=>progress.EstimatedCompletionAt!.Value).ToArray();deadlines.Should().HaveCountGreaterThan(2);for(var index=1;index<deadlines.Length;index++)(deadlines[index]<=deadlines[index-1]+TimeSpan.FromSeconds(1)).Should().BeTrue("routine progress must count down against one stable deadline");
    }
    private sealed class FixedProviderFactory(ILLMProvider provider):ILLMProviderFactory{public ILLMProvider Create(ConnectionProfile connection)=>provider;}
    private sealed class AutoReasoningProvider:ILLMProvider
    {
        public string ProviderType=>"test";public LlmRequest? ClassifierRequest{get;private set;}public LlmRequest? StreamRequest{get;private set;}
        public async IAsyncEnumerable<ModelEvent> StreamAsync(LlmRequest request,[EnumeratorCancellation]CancellationToken cancellationToken=default){StreamRequest=request;yield return new TextDeltaEvent("done");yield return new ModelCompletedEvent("stop");await Task.CompletedTask;}
        public Task<LlmResponse> CompleteAsync(LlmRequest request,CancellationToken cancellationToken=default){ClassifierRequest=request;return Task.FromResult(new LlmResponse("ultra",[],null,"stop"));}
        public Task<IReadOnlyList<string>> ListModelsAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult<IReadOnlyList<string>>([]);
        public Task<ConnectionTestResult> TestConnectionAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult(new ConnectionTestResult(true,"ok",TimeSpan.Zero));
    }
    private sealed class TwoTurnProvider:ILLMProvider
    {
        public string ProviderType=>"test";public int Calls{get;private set;}public LlmRequest? FirstRequest{get;private set;}public LlmRequest? SecondRequest{get;private set;}
        public async IAsyncEnumerable<ModelEvent> StreamAsync(LlmRequest request,[EnumeratorCancellation]CancellationToken cancellationToken=default){Calls++;if(Calls==1){FirstRequest=request;yield return new ToolCallStartedEvent("c1","echo");yield return new ToolCallArgumentsEvent("c1","{\"value\":\"x\"}");yield return new ModelCompletedEvent("tool_calls");}else{SecondRequest=request;yield return new TextDeltaEvent("final");yield return new ModelCompletedEvent("stop");}await Task.CompletedTask;}
        public Task<LlmResponse> CompleteAsync(LlmRequest request,CancellationToken cancellationToken=default)=>throw new NotSupportedException();public Task<IReadOnlyList<string>> ListModelsAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult<IReadOnlyList<string>>([]);public Task<ConnectionTestResult> TestConnectionAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult(new ConnectionTestResult(true,"ok",TimeSpan.Zero));
    }
    private sealed class RepeatingToolProvider(int toolIterations):ILLMProvider
    {
        public string ProviderType=>"test";public int Calls{get;private set;}
        public async IAsyncEnumerable<ModelEvent> StreamAsync(LlmRequest request,[EnumeratorCancellation]CancellationToken cancellationToken=default){Calls++;if(Calls<=toolIterations){var id=$"c{Calls}";yield return new ToolCallStartedEvent(id,"echo");yield return new ToolCallArgumentsEvent(id,$"{{\"value\":\"x{Calls}\"}}");yield return new ModelCompletedEvent("tool_calls");}else{yield return new TextDeltaEvent("complete");yield return new ModelCompletedEvent("stop");}await Task.CompletedTask;}
        public Task<LlmResponse> CompleteAsync(LlmRequest request,CancellationToken cancellationToken=default)=>throw new NotSupportedException();public Task<IReadOnlyList<string>> ListModelsAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult<IReadOnlyList<string>>([]);public Task<ConnectionTestResult> TestConnectionAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult(new ConnectionTestResult(true,"ok",TimeSpan.Zero));
    }
    private sealed class ToolUntilDisabledProvider:ILLMProvider
    {
        public string ProviderType=>"test";public int Calls{get;private set;}public LlmRequest? FinalRequest{get;private set;}
        public async IAsyncEnumerable<ModelEvent> StreamAsync(LlmRequest request,[EnumeratorCancellation]CancellationToken cancellationToken=default){Calls++;if(request.Tools.Count==0){FinalRequest=request;yield return new TextDeltaEvent("forced final");yield return new ModelCompletedEvent("stop");}else{var id=$"c{Calls}";yield return new ToolCallStartedEvent(id,"echo");yield return new ToolCallArgumentsEvent(id,$"{{\"value\":\"x{Calls}\"}}");yield return new ModelCompletedEvent("tool_calls");}await Task.CompletedTask;}
        public Task<LlmResponse> CompleteAsync(LlmRequest request,CancellationToken cancellationToken=default)=>throw new NotSupportedException();public Task<IReadOnlyList<string>> ListModelsAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult<IReadOnlyList<string>>([]);public Task<ConnectionTestResult> TestConnectionAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult(new ConnectionTestResult(true,"ok",TimeSpan.Zero));
    }
