    {
        public string ProviderType=>"test";public int Calls{get;private set;}
        public async IAsyncEnumerable<ModelEvent> StreamAsync(LlmRequest request,[EnumeratorCancellation]CancellationToken cancellationToken=default){Calls++;if(request.Tools.Count==0){yield return new TextDeltaEvent("forced final");yield return new ModelCompletedEvent("stop");}else{var id=$"c{Calls}";yield return new ToolCallStartedEvent(id,"echo");yield return new ToolCallArgumentsEvent(id,"{\"value\":\"same\"}");yield return new ModelCompletedEvent("tool_calls");}await Task.CompletedTask;}
        public Task<LlmResponse> CompleteAsync(LlmRequest request,CancellationToken cancellationToken=default)=>throw new NotSupportedException();public Task<IReadOnlyList<string>> ListModelsAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult<IReadOnlyList<string>>([]);public Task<ConnectionTestResult> TestConnectionAsync(ConnectionProfile connection,CancellationToken cancellationToken=default)=>Task.FromResult(new ConnectionTestResult(true,"ok",TimeSpan.Zero));
    }
    private sealed class PlannedBudgetProvider:ILLMProvider
    {
